(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.025-t*0.15)*8+Math.cos((y+w1y)*0.03+t*0.1)*6;
  const w2y = Math.cos((y+w1y)*0.025+t*0.18)*8+Math.sin((x+w1x)*0.028-t*0.12)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*55, 0.11, 2.1],
    [400+Math.cos(t*0.38+1)*60, 200+Math.sin(t*0.72+4)*50, 0.13, 1.4],
    [200+Math.sin(t*0.52+6)*90, 220+Math.cos(t*0.42+3)*65, 0.055, 2.8],
    [300+Math.cos(t*0.58+2)*85, 30+Math.sin(t*0.48+5)*60, 0.095, 1.6]
  ];
  let aS = 0, iS = 0, hS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    hS += Math.sin(d*f*1.3 - t*sp*0.8 + 3.0);
  }
  const act = aS/10, inh = iS/10, har = hS/10;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const pulse = Math.sin(dist*0.03-t*0.8)*0.3+Math.sin(dist*0.07-t*1.6)*0.15;
  const r1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);
  const r2 = Math.tanh((har*0.5 + act*inh*0.3 + pulse)*1.8);
  const cross = Math.tanh((r1*r2 + r1*0.6 - r2*0.4)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const edgeGlow = Math.exp(-Math.abs(cross)*3)*0.4;
  const blend = cross*0.6 + cell*0.15 + edgeGlow*0.25;
  const v = blend*0.5+0.5;
  const pal = [[5,10,45],[12,35,85],[18,75,120],[25,135,145],[60,175,140],[170,195,80],[220,170,55],[215,110,65],[185,55,75],[120,25,55],[45,12,42],[5,10,45]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.75+Math.sin(cross*Math.PI)*0.25;
  const edge = Math.abs(cross)>0.65?1.2:Math.abs(cross)>0.4?1.08:1.0;
  const glow = 1.0+edgeGlow*0.5;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*glow)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*glow)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*glow)|0
  ];
}
